import React from 'react';

const Navbar = ({ currentView, setCurrentView, usuario, onLogout }) => {
  return (
    <nav className="bg-gradient-to-r from-purple-600 via-blue-600 to-cyan-600 shadow-2xl sticky top-0 z-50 backdrop-blur-lg">
      <div className="container mx-auto px-6">
        <div className="flex items-center justify-between h-20">
          <div className="flex items-center space-x-4 group">
            <div className="text-5xl transform transition-transform duration-300 group-hover:scale-110 group-hover:rotate-12">
              🖥️
            </div>
            <div>
              <h1 className="text-2xl font-extrabold text-white tracking-tight">
                Sistema de Turnos
              </h1>
              <p className="text-xs text-purple-100 font-medium">Gestión de Laboratorios</p>
            </div>
          </div>

          <div className="hidden md:flex items-center space-x-3">
            {usuario.rol === 'ESTUDIANTE' && (
              <>
                <button
                  onClick={() => setCurrentView('disponibilidad')}
                  className={`px-5 py-2.5 rounded-xl font-semibold transition-all duration-300 transform hover:scale-105 ${
                    currentView === 'disponibilidad'
                      ? 'bg-white text-purple-600 shadow-lg'
                      : 'text-white hover:bg-white/20 backdrop-blur-sm'
                  }`}
                >
                  <span className="text-lg mr-2">📅</span>
                  Disponibilidad
                </button>

                <button
                  onClick={() => setCurrentView('mis-reservas')}
                  className={`px-5 py-2.5 rounded-xl font-semibold transition-all duration-300 transform hover:scale-105 ${
                    currentView === 'mis-reservas'
                      ? 'bg-white text-purple-600 shadow-lg'
                      : 'text-white hover:bg-white/20 backdrop-blur-sm'
                  }`}
                >
                  <span className="text-lg mr-2">📋</span>
                  Mis Reservas
                </button>
              </>
            )}

            {usuario.rol === 'PROFESOR' && (
              <button
                onClick={() => setCurrentView('profesor')}
                className={`px-5 py-2.5 rounded-xl font-semibold transition-all duration-300 transform hover:scale-105 ${
                  currentView === 'profesor'
                    ? 'bg-white text-orange-600 shadow-lg'
                    : 'text-white hover:bg-white/20 backdrop-blur-sm'
                }`}
              >
                <span className="text-lg mr-2">🔧</span>
                Panel Profesor
              </button>
            )}

            <div className="border-l-2 border-white/30 pl-4 ml-4">
              <div className="text-sm text-white font-medium">
                <div className="flex items-center space-x-2">
                  <span className="text-lg">👤</span>
                  <span>{usuario.nombre}</span>
                </div>
                <span className={`inline-block mt-1 badge ${
                  usuario.rol === 'PROFESOR' ? 'badge-warning' : 'badge-info'
                }`}>
                  {usuario.rol}
                </span>
              </div>
              <button
                onClick={onLogout}
                className="text-xs text-white hover:text-red-200 mt-2 font-semibold transition-colors duration-200 flex items-center space-x-1"
              >
                <span>🚪</span>
                <span>Cerrar sesión</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
